-- Sprint 6 Phase 1: Template Marketplace
CREATE TABLE IF NOT EXISTS "templates" ("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text, "workspace_id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "type" TEXT NOT NULL DEFAULT 'full_pipeline', "category" TEXT NOT NULL DEFAULT 'general', "language" TEXT NOT NULL DEFAULT 'en', "country" TEXT NOT NULL DEFAULT 'ALL', "thumbnail_url" TEXT NOT NULL DEFAULT '', "content" TEXT NOT NULL, "pricing" TEXT NOT NULL DEFAULT 'free', "price_credits" INTEGER NOT NULL DEFAULT 0, "tags" TEXT NOT NULL DEFAULT '', "downloads" INTEGER NOT NULL DEFAULT 0, "likes" INTEGER NOT NULL DEFAULT 0, "rating" REAL NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'draft', "is_featured" BOOLEAN NOT NULL DEFAULT false, "is_official" BOOLEAN NOT NULL DEFAULT false, "created_by" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "templates_workspace_id_idx" ON "templates"("workspace_id"); CREATE INDEX IF NOT EXISTS "templates_type_idx" ON "templates"("type"); CREATE INDEX IF NOT EXISTS "templates_category_idx" ON "templates"("category"); CREATE INDEX IF NOT EXISTS "templates_status_idx" ON "templates"("status"); CREATE INDEX IF NOT EXISTS "templates_is_featured_idx" ON "templates"("is_featured"); CREATE INDEX IF NOT EXISTS "templates_downloads_idx" ON "templates"("downloads");
CREATE TABLE IF NOT EXISTS "template_versions" ("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text, "template_id" TEXT NOT NULL REFERENCES "templates"("id") ON DELETE CASCADE, "version" INTEGER NOT NULL DEFAULT 1, "content" TEXT NOT NULL, "changelog" TEXT NOT NULL DEFAULT '', "created_at" TIMESTAMP NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS "template_versions_template_id_idx" ON "template_versions"("template_id");
CREATE TABLE IF NOT EXISTS "template_reviews" ("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text, "template_id" TEXT NOT NULL REFERENCES "templates"("id") ON DELETE CASCADE, "user_id" TEXT NOT NULL, "rating" INTEGER NOT NULL, "comment" TEXT NOT NULL DEFAULT '', "created_at" TIMESTAMP NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS "template_reviews_template_id_user_id_key" ON "template_reviews"("template_id", "user_id");
CREATE TABLE IF NOT EXISTS "template_downloads" ("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text, "template_id" TEXT NOT NULL REFERENCES "templates"("id") ON DELETE CASCADE, "workspace_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "credits_used" INTEGER NOT NULL DEFAULT 0, "created_at" TIMESTAMP NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS "template_downloads_template_id_idx" ON "template_downloads"("template_id");
